/* The HST back channel's tables (modem/hst_tabs, generated by
 * tools/gen_hst_tabs.py) and its 8-DPSK transmitter (modem/hst_back.c);
 * docs/history/hst-facts.md, "Back channel".
 *
 *   steps        hst_bstep is BF §3's row, and the firmware's 0x43705261
 *                read a nibble at a time from the low end
 *   scr17        1 + x^-14 + x^-17 without V.22bis's 64-ones rule: 64 ones
 *                on the line pass uninverted; a test-side model agrees bit
 *                for bit; descramble(scramble(x)) = x over 10^4 PRBS bits
 *   filters      hst_bbpf: 250-500 Hz flat, >= 50 dB down at 600 Hz and
 *                above (and at 150 Hz and below); hst_hbpf: 600-3400 Hz flat,
 *                >= 40 dB down at 500 Hz and below
 *   tx_phase     known line tribits after the preamble: the phases a
 *                test-side matched correlator measures step by
 *                hst_bstep[t] x 45 degrees and sit on 22.5 + 45 k degrees
 *                (450 at 375 Hz, 300 at 350 Hz; the preamble's symbols too)
 *   tx_speed     450 then 300 by hst_btx_set_speed: the 300 symbols step
 *                right; hst_btx_stop: silence once the pulses have drained
 *   tx_spectrum  10 s of random data at 450 and at 300: power at 600 Hz and
 *                above >= 50 dB below the in-band peak; the occupied band at
 *                -20 dB 274-476 Hz (450) and 283-417 Hz (300) within
 *                +-10 Hz; the line level is the one asked for
 *
 * The output (the golden file) holds exact integers and one pass or fail
 * line per bound; the measured values, from the test's own floating-point
 * arithmetic, only with HST_VERBOSE set. Each case seeds its own random
 * data, so a case run alone prints what it prints in the whole run. */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "test.h"
#include "../modem/scramble.h"
#include "../modem/hst_tabs.h"
#include "../modem/hst.h"

#define FS 8000
#define PI 3.14159265358979323846

/* ---- a test-side model of the scrambler (facts: out = in ^ out[n-14] ^ out[n-17]) ---- */
typedef struct { uint32_t h; } mscr_t;          /* bit 0 = newest line bit */
static int mscr_line(mscr_t *m, int di)
{
    int ds = (di ^ (int)(m->h >> 13) ^ (int)(m->h >> 16)) & 1;
    m->h = (m->h << 1) | (uint32_t)ds;
    return ds;
}
/* the data bit that puts `ds` on the line next */
static int mscr_data_for(mscr_t *m, int ds)
{
    int di = (ds ^ (int)(m->h >> 13) ^ (int)(m->h >> 16)) & 1;
    m->h = (m->h << 1) | (uint32_t)(ds & 1);
    return di;
}

static int verbose;
/* one bound: its line, and its check */
static void bound(const char *what, int ok)
{
    printf("  %s: %s\n", what, ok ? "pass" : "FAIL");
    CHECK(ok);
}

static uint32_t prbs;
static void prbs_seed(uint32_t s) { prbs = s; }
static int prbs_bit(void)
{
    prbs = prbs * 1664525u + 1013904223u;
    return (int)(prbs >> 27) & 1;
}

/* ---- the transmitter's bit source ---- */
typedef struct {
    mscr_t model;          /* the line's scrambler, followed bit for bit */
    int    nline;          /* line tribits wanted after the preamble, sent cyclically */
    const uint8_t *line;
    int    pos;            /* data bits handed out */
    int    random;         /* random data instead */
} src_t;
static int getbit(void *user)
{
    src_t *s = (src_t *)user;
    int ds;
    if (s->random) return prbs_bit();
    ds = (s->line[(s->pos / 3) % s->nline] >> (s->pos % 3)) & 1;      /* tribit LSB first */
    s->pos++;
    return mscr_data_for(&s->model, ds);
}
/* a source for `nline` known line tribits, over and over, after a preamble of npre symbols */
static void src_line(src_t *s, const uint8_t *line, int nline, int npre)
{
    int i;
    memset(s, 0, sizeof *s);
    s->line = line; s->nline = nline;
    for (i = 0; i < 3 * npre; i++) (void)mscr_line(&s->model, 1);    /* the preamble's ones */
}
/* the line tribit of symbol k (from the preamble's start), and the scrambler model of the preamble */
static int line_tribit(mscr_t *pre, const uint8_t *line, int nline, int npre, int k)
{
    int b, t = 0;
    if (k >= npre) return line[(k - npre) % nline];
    for (b = 0; b < 3; b++) t |= mscr_line(pre, 1) << b;
    return t;
}

/* ---- the test's own matched filter: RRC, beta 0.35, +-10 symbols, Hann ---- */
static double rrc(double t)
{
    const double a = 0.35;
    if (fabs(t) < 1e-9) return 1 - a + 4 * a / PI;
    if (fabs(fabs(t) - 1 / (4 * a)) < 1e-9)
        return a / sqrt(2) * ((1 + 2 / PI) * sin(PI / (4 * a)) + (1 - 2 / PI) * cos(PI / (4 * a)));
    return (sin(PI * t * (1 - a)) + 4 * a * t * cos(PI * t * (1 + a))) / (PI * t * (1 - 16 * a * a * t * t));
}
#define MFL 10
static double mf(double t) { return fabs(t) >= MFL ? 0 : rrc(t) * (0.5 + 0.5 * cos(PI * t / MFL)); }

/* the phase, in degrees [0, 360), of the symbol centred at sample c (T samples a symbol) */
static double sym_phase(const int16_t *x, int n, double fc, double c, double T)
{
    double re = 0, im = 0, g, ph;
    int i, i0 = (int)floor(c - MFL * T), i1 = (int)ceil(c + MFL * T);
    if (i0 < 0) i0 = 0;
    if (i1 > n - 1) i1 = n - 1;
    for (i = i0; i <= i1; i++) {
        g = mf((i - c) / T) * x[i];
        re += g * cos(2 * PI * fc * i / FS);
        im -= g * sin(2 * PI * fc * i / FS);
    }
    ph = atan2(im, re) * 180 / PI;
    return ph < 0 ? ph + 360 : ph;
}
static double wrap180(double d)
{
    while (d > 180) d -= 360;
    while (d <= -180) d += 360;
    return d;
}

#define NBUF 24000
static int16_t buf[NBUF];

static void steps(void)
{
    static const int row[8] = { 1, 6, 2, 5, 0, 7, 3, 4 };     /* BF §3 */
    const uint32_t fw = 0x43705261u;
    int t;
    for (t = 0; t < 8; t++) {
        CHECK_EQ_I(hst_bstep[t], row[t]);
        CHECK_EQ_I(hst_bstep[t], (fw >> (4 * t)) & 15);
    }
}

static void scr17(void)
{
    scr_t s, d, v;
    mscr_t m = { 0 }, want = { 0 };
    int i, bad = 0, ones = 0, vdiff = 0, di, ds;

    /* data that puts 100 ones in a row on the line, from the zero state */
    scr_init(&s); scr_init(&v);
    for (i = 0; i < 100; i++) {
        di = mscr_data_for(&want, 1);
        ds = scr17_scramble(&s, di);
        ones += ds == 1;
        if (v22_scramble(&v, di) != ds) vdiff++;
    }
    CHECK_EQ_I(ones, 100);          /* no inversion after 64 ones */
    CHECK(vdiff > 0);               /* where v22_scramble inverts */

    /* against the model, and the round trip, over 10^4 PRBS bits */
    prbs_seed(0x1234567u);
    scr_init(&s); scr_init(&d);
    for (i = 0; i < 10000; i++) {
        di = prbs_bit();
        ds = scr17_scramble(&s, di);
        if (ds != mscr_line(&m, di)) bad++;
        if (scr17_descramble(&d, ds) != di) bad++;
    }
    CHECK_EQ_I(bad, 0);
    /* self-synchronising: a descrambler from another state is right after 17 bits */
    scr_init(&s); scr_init(&d); d.reg = 0x15A5Au;
    bad = 0;
    for (i = 0; i < 1000; i++) {
        di = prbs_bit();
        ds = scr17_scramble(&s, di);
        if (scr17_descramble(&d, ds) != di && i >= 17) bad++;
    }
    CHECK_EQ_I(bad, 0);
}

/* |H(f)| in dB of a Q15 FIR */
static double fir_db(const int16_t *h, int n, double f)
{
    double re = 0, im = 0;
    int i;
    for (i = 0; i < n; i++) {
        re += h[i] * cos(2 * PI * f * i / FS);
        im -= h[i] * sin(2 * PI * f * i / FS);
    }
    return 10 * log10((re * re + im * im) / (32768.0 * 32768.0) + 1e-30);
}

static void filters(void)
{
    double f, lo = 1e9, hi = -1e9, stop = -1e9;
    int i, sym = 1;
    for (i = 0; i < HST_BBPF_N; i++) sym &= hst_bbpf[i] == hst_bbpf[HST_BBPF_N - 1 - i];
    for (i = 0; i < HST_HBPF_N; i++) sym &= hst_hbpf[i] == hst_hbpf[HST_HBPF_N - 1 - i];
    CHECK(sym);                                   /* linear phase */

    for (f = 250; f <= 500; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d < lo) lo = d; if (d > hi) hi = d; }
    for (f = 600; f <= 4000; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d > stop) stop = d; }
    for (f = 0; f <= 150; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d > stop) stop = d; }
    printf("bbpf: %d taps\n", HST_BBPF_N);
    if (verbose) printf("  (250-500 Hz %.3f to %.3f dB, <= 150 and >= 600 Hz at most %.2f dB)\n", lo, hi, stop);
    bound("250-500 Hz within 0.5 dB", lo >= -0.5 && hi <= 0.5);
    bound("50 dB down at <= 150 Hz and >= 600 Hz", stop <= -50);

    lo = 1e9; hi = -1e9; stop = -1e9;
    for (f = 600; f <= 3400; f += 2) { double d = fir_db(hst_hbpf, HST_HBPF_N, f); if (d < lo) lo = d; if (d > hi) hi = d; }
    for (f = 0; f <= 500; f += 2) { double d = fir_db(hst_hbpf, HST_HBPF_N, f); if (d > stop) stop = d; }
    printf("hbpf: %d taps\n", HST_HBPF_N);
    if (verbose) printf("  (600-3400 Hz %.3f to %.3f dB, <= 500 Hz at most %.2f dB)\n", lo, hi, stop);
    bound("600-3400 Hz within 0.5 dB", lo >= -0.5 && hi <= 0.5);
    bound("40 dB down at <= 500 Hz", stop <= -40);
}

/* line tribits: every value in turn, then a mixed run */
static void line_tribits(uint8_t *t, int n)
{
    int i;
    for (i = 0; i < n; i++)
        t[i] = (uint8_t)(i < 8 ? i : i < 72 ? ((i - 8) >> 3 ^ (i - 8)) & 7 : (i * 5 + 3) & 7);
}

/* the preamble then known line tribits at `bps`; every symbol's phase */
static void phase_run(int bps)
{
    hst_btx_t tx;
    src_t src;
    mscr_t pre = { 0 };
    uint8_t line[72];
    const int npre = bps == 450 ? 45 : 30, nline = 72, nsym = npre + nline;
    const double T = bps == 450 ? FS / 150.0 : FS / 100.0, fc = bps == 450 ? 375 : 350;
    int k, n, t, p = 0, step_bad = 0, grid_bad = 0;
    double ph, prev = 0, emax_step = 0, emax_grid = 0;

    line_tribits(line, nline);
    src_line(&src, line, nline, npre);
    hst_btx_init(&tx, bps, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < (int)((nsym + HST_BL + MFL + 2) * T) && n < NBUF; n++) buf[n] = hst_btx_tick(&tx);
    for (k = 0; k < nsym; k++) {
        double eg, es;
        t = line_tribit(&pre, line, nline, npre, k);
        p = (p + hst_bstep[t]) & 7;
        ph = sym_phase(buf, n, fc, (k + HST_BL / 2.0) * T, T);
        eg = fabs(wrap180(ph - (22.5 + 45 * p)));
        es = k ? fabs(wrap180(ph - prev - 45 * hst_bstep[t])) : 0;
        if (eg > emax_grid) emax_grid = eg;
        if (es > emax_step) emax_step = es;
        grid_bad += eg > 3;
        step_bad += es > 3;
        prev = ph;
    }
    printf("tx_phase %d: %d symbols (%d preamble)\n", bps, nsym, npre);
    if (verbose) printf("  (step error at most %.3f deg, grid error at most %.3f deg)\n", emax_step, emax_grid);
    bound("every step hst_bstep[t] x 45 deg within 3 deg", step_bad == 0);
    bound("every symbol on 22.5 + 45 k deg within 3 deg", grid_bad == 0);
    CHECK(src.pos >= 3 * nline);
}

static void tx_phase(void)
{
    phase_run(450);
    phase_run(300);
}

static void tx_speed(void)
{
    hst_btx_t tx;
    src_t src;
    mscr_t pre = { 0 };
    uint8_t line[72];
    int n, k, n300 = -1, s450 = 0, t, p = 0, tail = 0, bad = 0;
    double ph, prev = 0;

    line_tribits(line, 72);
    src_line(&src, line, 72, 45);
    hst_btx_init(&tx, 450, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < 3000; n++) buf[n] = hst_btx_tick(&tx);
    hst_btx_set_speed(&tx, 300);
    for (; n < 12000; n++) {
        buf[n] = hst_btx_tick(&tx);
        if (n300 < 0 && tx.newsym && tx.bps == 300) n300 = n;
    }
    CHECK(n300 >= 3000 && n300 <= 3000 + 54);       /* at the next 450 symbol */
    /* 450 symbols began at 0, 53 1/3, ... before n300 */
    while (s450 * (FS / 150.0) < n300 - 0.01) s450++;
    for (k = 0; k < s450; k++) p = (p + hst_bstep[line_tribit(&pre, line, 72, 45, k)]) & 7;
    for (k = 0; k < 60; k++) {
        t = line_tribit(&pre, line, 72, 45, s450 + k);
        p = (p + hst_bstep[t]) & 7;
        ph = sym_phase(buf, n, 350, n300 + (k + HST_BL / 2.0) * 80, 80);
        /* from the 12th, the measurement's window is clear of the 450 tail */
        if (k > 12 && fabs(wrap180(ph - prev - 45 * hst_bstep[t])) > 3) bad++;
        if (k >= 12 && fabs(wrap180(ph - (22.5 + 45 * p))) > 3) bad++;
        prev = ph;
    }
    printf("tx_speed: 450 -> 300 at sample %d, after %d symbols at 450\n", n300, s450);
    bound("the 300 symbols' steps and grid within 3 deg", bad == 0);

    hst_btx_stop(&tx);
    for (n = 0; n < (HST_BL + 1) * 80; n++) (void)hst_btx_tick(&tx);
    for (n = 0; n < 1000; n++) tail |= hst_btx_tick(&tx);
    bound("silence once the pulses have drained", tail == 0);
}

/* floor(sqrt(v)) */
static int64_t isqrt64(int64_t v)
{
    int64_t r = (int64_t)sqrt((double)v);
    while (r * r > v) r--;
    while ((r + 1) * (r + 1) <= v) r++;
    return r;
}

/* ---- spectrum: Welch, Hann, 4096 points, half overlap ---- */
#define NF 4096
static void fft(double *re, double *im, int n)
{
    int i, j, k, len;
    for (i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) { double t = re[i]; re[i] = re[j]; re[j] = t; t = im[i]; im[i] = im[j]; im[j] = t; }
    }
    static double twr[NF / 2], twi[NF / 2];
    if (twi[1] == 0)
        for (k = 0; k < NF / 2; k++) { twr[k] = cos(-2 * PI * k / NF); twi[k] = sin(-2 * PI * k / NF); }
    for (len = 2; len <= n; len <<= 1) {
        for (i = 0; i < n; i += len)
            for (k = 0; k < len / 2; k++) {
                double wr = twr[k * (NF / len)], wi = twi[k * (NF / len)];
                double xr = re[i + k + len / 2] * wr - im[i + k + len / 2] * wi;
                double xi = re[i + k + len / 2] * wi + im[i + k + len / 2] * wr;
                re[i + k + len / 2] = re[i + k] - xr; im[i + k + len / 2] = im[i + k] - xi;
                re[i + k] += xr; im[i + k] += xi;
            }
    }
}

static void spectrum_run(int bps, double lo_want, double hi_want)
{
    static double re[NF], im[NF], psd[NF / 2 + 1];
    static int16_t x[10 * FS];
    hst_btx_t tx;
    src_t src;
    int n, i, seg, nseg = 0, pk = 0, lo, hi;
    int64_t sq = 0, rms;
    double peak, out = 0, hz = (double)FS / NF;

    prbs_seed(0x2468ACEu + (uint32_t)bps);
    memset(&src, 0, sizeof src);
    src.random = 1;
    hst_btx_init(&tx, bps, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < FS; n++) (void)hst_btx_tick(&tx);         /* past the preamble */
    for (n = 0; n < 10 * FS; n++) { x[n] = hst_btx_tick(&tx); sq += (int64_t)x[n] * x[n]; }
    rms = isqrt64(sq / (10 * FS));

    memset(psd, 0, sizeof psd);
    for (seg = 0; seg + NF <= 10 * FS; seg += NF / 2, nseg++) {
        for (i = 0; i < NF; i++) {
            re[i] = x[seg + i] * (0.5 - 0.5 * cos(2 * PI * i / NF));
            im[i] = 0;
        }
        fft(re, im, NF);
        for (i = 0; i <= NF / 2; i++) psd[i] += re[i] * re[i] + im[i] * im[i];
    }
    for (i = 0; i <= NF / 2; i++) if (psd[i] > psd[pk]) pk = i;
    peak = psd[pk];
    for (i = (int)ceil(600 / hz); i <= NF / 2; i++) if (psd[i] > out) out = psd[i];
    for (lo = pk; lo > 0 && psd[lo - 1] >= peak / 100; lo--) ;
    for (hi = pk; hi < NF / 2 && psd[hi + 1] >= peak / 100; hi++) ;
    printf("tx_spectrum %d: level %d (asked 4000), %d segments\n", bps, (int)rms, nseg);
    if (verbose)
        printf("  (peak at %.1f Hz, -20 dB band %.1f-%.1f Hz, >= 600 Hz %.2f dB)\n",
               pk * hz, lo * hz, hi * hz, 10 * log10(out / peak));
    bound("level within 0.3 dB of 4000", rms >= 3863 && rms <= 4141);     /* 4000 x 10^(-+0.3/20) */
    bound(">= 600 Hz at least 50 dB below the peak", 10 * log10(out / peak) <= -50);
    {
        char what[64];
        snprintf(what, sizeof what, "-20 dB band within 10 Hz of %d-%d Hz", (int)lo_want, (int)hi_want);
        bound(what, fabs(lo * hz - lo_want) <= 10 && fabs(hi * hz - hi_want) <= 10);
    }
    CHECK(nseg >= 30);
}

static void tx_spectrum(void)
{
    spectrum_run(450, 274, 476);
    spectrum_run(300, 283, 417);
}

int main(int argc, char **argv)
{
    int only = t_case_arg(argc, argv, 6);
    verbose = getenv("HST_VERBOSE") != NULL;
    if (T_CASE(only, 1)) steps();
    if (T_CASE(only, 2)) scr17();
    if (T_CASE(only, 3)) filters();
    if (T_CASE(only, 4)) tx_phase();
    if (T_CASE(only, 5)) tx_speed();
    if (T_CASE(only, 6)) tx_spectrum();
    T_REPORT("test_hst_back");
}
